import csv

# Step 2: Find the row with customer_id='C-007' and extract name and region
customer = None
with open(file, newline='', encoding='utf-8', errors='replace') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row.get('customer_id') == 'C-007':
            customer = {
                'name': row.get('customer_name', '').strip(),
                'region': row.get('region', '').strip()
            }
            break

print("Extracted customer:", customer)
